# Hypothesis: 'answer-phase math answer statement' (next token = value) is linearly separable at the exact L23 MLP input z with ~0 FP.
b_v2 = gv2['b'].astype(np.float32)
def zn(Xb):
    Xb = np.asarray(Xb, np.float32); r = np.sqrt((Xb**2).mean(1, keepdims=True) + 1e-6)
    return Xb / r * (1 + g_ln23)
lens13 = (tok13 >= 0).sum(1)
rng = np.random.default_rng(13)
pos, negS, negS_kind, pos_txt, negS_txt = [], [], [], [], []
stmt_set = set()
for i, c in enumerate(idx13):
    for (t, ph, nx) in c['S']:
        z = zn(H13[i, 1, t][None])[0]; stmt_set.add((i, t))
        if c['kind'] == 'math' and ph == 'ans': pos.append(z); pos_txt.append(i)
        else: negS.append(z); negS_kind.append(c['kind'] + '_' + ph); negS_txt.append(i)
pos = np.array(pos); negS = np.array(negS); pos_txt = np.array(pos_txt); negS_txt = np.array(negS_txt)
R_i, R_t = [], []
for i in range(len(idx13)):
    ts = rng.choice(lens13[i], size=min(600, lens13[i]), replace=False)
    for t in ts:
        if (i, t) not in stmt_set: R_i.append(i); R_t.append(t)
R_i = np.array(R_i); R_t = np.array(R_t)
negR = np.concatenate([zn(H13[i, 1, R_t[R_i == i]]) for i in range(len(idx13))]); negR_txt = np.concatenate([R_i[R_i == i] for i in range(len(idx13))])
print('pos', pos.shape, 'negS', negS.shape, 'negR', negR.shape)
print('b.z  pos: %.3f+-%.3f  negR: %.3f+-%.3f' % ((pos@b_v2).mean(), (pos@b_v2).std(), (negR@b_v2).mean(), (negR@b_v2).std()))
def lda(P, N, lam=0.05):
    mu_p, mu_n = P.mean(0), N.mean(0)
    C = np.cov(np.concatenate([P - mu_p, N - mu_n]).T)
    C += lam * np.trace(C) / C.shape[0] * np.eye(C.shape[0])
    w = np.linalg.solve(C, mu_p - mu_n); return w / np.sqrt(w @ C @ w)
folds = np.arange(len(idx13)) % 5
for lam in [0.02, 0.1, 0.3]:
    hp, mx = [], collections.defaultdict(list)
    for f in range(5):
        tr_p, tr_n = pos[folds[pos_txt] != f], np.concatenate([negS[folds[negS_txt] != f], negR[folds[negR_txt] != f]])
        w = lda(tr_p, tr_n, lam)
        sp, sn = pos[folds[pos_txt] == f] @ w, negR[folds[negR_txt] == f] @ w
        thr = np.percentile(tr_n @ w, 99.99)
        hp.append((sp > thr).mean())
        for k in set(negS_kind):
            m = (folds[negS_txt] == f) & (np.array(negS_kind) == k)
            if m.any(): mx[k].append(float((negS[m] @ w > thr).mean()))
        mx['rand'].append(float((sn > thr).mean()))
    print('lam', lam, 'held-out pos hit@p99.99(train neg) %.2f' % np.mean(hp), {k: round(float(np.mean(v)), 4) for k, v in mx.items()})

