# Grade pass 20 MCQ (v4b vs start) + rebuilt IF checker on pass 18 (v4b) and pass 9 (v2).
g20s = rj('/work/gen_20_start.jsonl'); g20e = rj('/work/gen_20_edited.jsonl')
R20s, R20e = grade12(g20s), grade12(g20e); ks20 = sorted(R20s)
for name, R in [('start', R20s), ('v4b', R20e)]:
    print('MCQ', name, 'acc %.1f noans %.1f cut %.1f multi %.1f' % tuple(100*np.mean([bool(R[k][f]) if f != 'noans' else R[k]['pred'] is None for k in ks20]) for f in ['ok', 'noans', 'cut', 'multi']))
for f in ['ok', 'cut', 'multi']:
    d = np.array([R20e[k][f] - R20s[k][f] for k in ks20], float); print('  MCQ', f, 'diff %+.1f SE %.1f' % (100*d.mean(), 100*d.std(ddof=1)/np.sqrt(len(d))), 'up', int((d>0).sum()), 'down', int((d<0).sum()))
d = np.array([(R20e[k]['pred'] is None) - (R20s[k]['pred'] is None) for k in ks20], float); print('  MCQ noans diff %+.1f SE %.1f' % (100*d.mean(), 100*d.std(ddof=1)/np.sqrt(len(d))))
ifd_by = {e['iid']: e for e in ifp}
def nwords(s): return len(re.findall(r"\b\w+\b", s))
def check_spec(resp, s, prompt):
    t = s[0]; v = resp
    if t == 'paras':
        ps_ = re.split(r'\s?\*\*\*\s?', v); n = len(ps_)
        for i, p in enumerate(ps_):
            if not p.strip():
                if i == 0 or i == len(ps_) - 1: n -= 1
                else: return False
        return n == s[1]
    if t == 'ps': return bool(re.findall(r'\s*p\.\s?s\..*$', v.lower(), flags=re.MULTILINE))
    if t == 'title': return any(x.strip('<>').strip() for x in re.findall(r'<<[^\n]+>>', v))
    if t == 'lower': return v == v.lower()
    if t == 'end': return v.strip().strip('"').lower().endswith(s[1].strip().lower())
    if t == 'minsent': return len([x for x in re.split(r'(?<=[.!?])\s+', v.strip()) if x.strip()]) >= s[1]
    if t == 'highlight': return len([h for h in re.findall(r'\*[^\n\*]*\*', v) if h.strip('*').strip()]) + len([h for h in re.findall(r'\*\*[^\n\*]*\*\*', v) if h.strip('*').strip()]) >= s[1]
    if t == 'placeholders': return len(re.findall(r'\[.*?\]', v)) >= s[1]
    if t == 'quotes': vv = v.strip(); return len(vv) > 1 and vv[0] == '"' and vv[-1] == '"'
    if t == 'nocomma': return ',' not in v
    if t == 'min_words': return nwords(v) >= s[1]
    if t == 'max_words': return nwords(v) < s[1] if 'less than' in prompt.lower() else nwords(v) <= s[1]
    if t == 'keyword': return len(re.findall(r'\b%s\b' % re.escape(s[1]), v, flags=re.IGNORECASE)) >= s[2]
    if t == 'bullets': return len(re.findall(r'^\s*\*[^\*].*$', v, flags=re.MULTILINE)) + len(re.findall(r'^\s*-.*$', v, flags=re.MULTILINE)) == s[1]
    if t == 'json':
        vv = v.strip()
        for pre_ in ['```json', '```Json', '```JSON', '```']: vv = vv[len(pre_):] if vv.startswith(pre_) else vv
        vv = vv[:-3] if vv.endswith('```') else vv
        try: json.loads(vv.strip()); return True
        except Exception: return False
    return None
def check_if(text, e):
    if '</think>' not in text: return False
    resp = text.split('</think>')[-1].strip()
    if resp.endswith('<|im_end|>'): resp = resp[:-10]
    return all(check_spec(resp, s, e['prompt']) for s in e['specs'])
