print('p9 src sample', src9[:2])
for P in ['9', '18']:
    S_ = {int(r['id'].split('/')[1]): r for r in rj('/work/gen_%s_start.jsonl' % P) if r['id'].startswith('prompt/')}
    E_ = {int(r['id'].split('/')[1]): r for r in rj('/work/gen_%s_edited.jsonl' % P) if r['id'].startswith('prompt/')}
    ks_ = [k for k in S_ if src9[k][0] == 'if']; iid = lambda k: src9[k][1] if isinstance(src9[k][1], str) else ifp[src9[k][1]]['iid']
    a = np.array([check_if(S_[k]['text'], ifd_by[iid(k)]) for k in ks_], float); b = np.array([check_if(E_[k]['text'], ifd_by[iid(k)]) for k in ks_], float); d = b - a
    print('IF pass', P, 'n', len(ks_), 'start %.1f edited %.1f diff %+.1f SE %.1f' % (100*a.mean(), 100*b.mean(), 100*d.mean(), 100*d.std(ddof=1)/np.sqrt(len(d))),
          '| cut s/e', sum(S_[k]['finish_reason']=='length' for k in ks_), sum(E_[k]['finish_reason']=='length' for k in ks_), '| multi s/e', sum(S_[k]['text'].count('</think>')>1 for k in ks_), sum(E_[k]['text'].count('</think>')>1 for k in ks_))

